def insertion_sort(arr):
    for i in range(1, len(arr)):
        key = arr[i]
        # Binary search for insertion point
        left, right = 0, i
        while left < right:
            mid = (left + right) // 2
            if arr[mid] > key:
                right = mid
            else:
                left = mid + 1
        # Shift elements
        for j in range(i, left, -1):
            arr[j] = arr[j - 1]
        arr[left] = key
